"""Mixed-task RL data (all generated by us): GSM-like, BBH-like (8 families, one per BBH tool), IFEval-like, combos.
Writes train.jsonl (5000) and test.jsonl (1000). Disjointness:
  gsm    : scaled-number GSM8K-train variants; train = sources in split A, test = sources in split B (disjoint source
           problems AND numbers; templates = the source problems).
  bbh    : teams' generators, train seed 100 (TR), test seed 102 (LK) -> disjoint items (same generator templates).
  ifeval : Team D's gen_data, train seed 100, test seed 102, any test prompt equal to a train prompt dropped.
  combo  : a gsm/bbh question (from that split's own pool) + ONE format constraint (7 constraint templates shared by
           train and test; the questions are disjoint). Reward = answer correct AND constraint satisfied.
Row: {id, type, sub, user, gold?, fam?, task?, instruction_id_list?, kwargs?}
"""
import os, sys, json, random, hashlib
OUT = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.environ.get('RLENVS', os.path.dirname(os.path.abspath(__file__))))
import envs as EV                                         # BBH generators (teams A/B/C), WSM_INTEG_DIR must be set
sys.path.insert(0, os.environ.get('IFDIR', os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', '..', 'ifeval', 'heldout')))
import gen_data as GD
sys.path.insert(0, os.environ.get('RLW_DIR', os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'wiring')))
import common as C

FIN = "Think step by step, then finish with a line of the form 'The answer is X.'"
CONSTR = [  # (instruction id, kwargs, sentence) -- all within the IFEval circuit's 14 rules
    ('change_case:english_lowercase', {}, 'Your entire response should be in English, and in all lowercase letters. No capital letters are allowed.'),
    ('change_case:english_capital', {}, 'Your entire response should be in English and in all capital letters.'),
    ('startend:quotation', {}, 'Wrap your entire response with double quotation marks.'),
    ('startend:end_checker', {'end_phrase': 'Is there anything else I can help with?'}, "Finish your response with this exact phrase: 'Is there anything else I can help with?'. No other words should follow this phrase."),
    ('detectable_format:title', {}, 'Your answer must contain a title, wrapped in double angular brackets, such as <<poem of joy>>.'),
    ('detectable_content:postscript', {'postscript_marker': 'P.S.'}, 'At the end of your response, please explicitly add a postscript starting with P.S.'),
    ('detectable_format:number_highlighted_sections', {'num_highlights': 2}, 'Highlight at least 2 sections in your answer with markdown, i.e. *highlighted section*.'),
]
BBH_TASKS = ['track3', 'track5', 'track7', 'order3', 'order5', 'order7', 'temporal', 'navigate', 'lies',
             'multistep_arithmetic_two', 'boolean_expressions', 'object_counting']


def gsm_rows(split, n, rng):
    tok = None
    pool = [r for r in C.load_train(split, which=('scaled',)) if len(r['q']) < 700]
    rng.shuffle(pool)
    return [dict(type='gsm', sub='gsm', user=r['q'] + '\n' + FIN, gold=r['gold'], q=r['q']) for r in pool[:n]]


def bbh_rows(split, n, rng):
    e = EV.Env('bbhcall')
    rows = e.rows(split, max(4, n // 9 + 4))
    by = {}
    for r in rows: by.setdefault(r['task'], []).append(r)
    out = []
    k = 0
    while len(out) < n:                                   # round-robin over the 12 BBH families (8 tools)
        t = BBH_TASKS[k % len(BBH_TASKS)]; k += 1
        if by.get(t): r = by[t].pop(); out.append(dict(type='bbh', sub=t, user=r['q'] + '\n' + FIN, gold=r['gold'], fam=r['fam'], task=r['task'], q=r['q']))
        if k > 100 * n: break
    rng.shuffle(out)
    return out


def ifeval_rows(seed, n, banned=()):
    rows = [r for r in GD.make(seed, max(2, n // 8 + 5), None) if r['prompt'] not in banned]
    random.Random(seed).shuffle(rows)
    return [dict(type='ifeval', sub=r['instruction_id_list'][0].split(':')[0], user=r['prompt'],
                 instruction_id_list=r['instruction_id_list'], kwargs=r['kwargs'], key=r.get('key', 0)) for r in rows[:n]]


def combo_rows(base, n, rng):
    out = []
    for r in base[:n]:
        cid, kw, sent = CONSTR[rng.randrange(len(CONSTR))]
        if r['type'] == 'bbh' and cid.startswith('change_case'): cid, kw, sent = CONSTR[2]   # case changes break BBH option letters
        d = dict(r); d['type'] = 'combo'; d['sub'] = r['type'] + '+' + cid.split(':')[1]
        d['user'] = r['user'] + '\n' + sent; d['instruction_id_list'] = [cid]; d['kwargs'] = [kw]; d['key'] = 0
        out.append(d)
    return out


def build(split, seed, n_gsm, n_bbh, n_if, n_combo, banned_if=()):
    rng = random.Random(seed)
    g = gsm_rows('A' if split == 'TR' else 'B', n_gsm + n_combo // 2, rng)
    b = bbh_rows(split, n_bbh + n_combo // 2, rng)
    i = ifeval_rows(seed, n_if, banned_if)
    combo = combo_rows(g[n_gsm:] + b[n_bbh:], n_combo, rng)
    rows = g[:n_gsm] + b[:n_bbh] + i + combo
    rng.shuffle(rows)
    for j, r in enumerate(rows): r['id'] = f'{split}{j}'
    return rows


if __name__ == '__main__':
    tr = build('TR', 100, 1500, 1500, 1200, 800)
    trp = {r['user'] for r in tr if r['type'] == 'ifeval'}
    te = build('LK', 102, 300, 330, 250, 150, banned_if=trp)
    trq = {r.get('q') for r in tr}
    te = [r for r in te if not (r['type'] in ('bbh', 'combo') and r.get('q') in trq)]
    nb = 0; te2 = []
    for r in te:                                         # keep 300 bbh after dropping train collisions
        if r['type'] == 'bbh':
            nb += 1
            if nb > 300: continue
        te2.append(r)
    te = te2
    from collections import Counter
    for nm, rows in (('train', tr), ('test', te)):
        json.dump(None, open(os.devnull, 'w'))
        with open(os.path.join(OUT, f'{nm}.jsonl'), 'w') as f:
            for r in rows: f.write(json.dumps(r) + '\n')
        print(nm, len(rows), Counter(r['type'] for r in rows), Counter(r['sub'] for r in rows if r['type'] == 'bbh').most_common(3))
    qs = lambda rows, t: {r.get('q', r['user']) for r in rows if r['type'] == t}
    print('overlap gsm', len(qs(tr, 'gsm') & qs(te, 'gsm')), 'bbh', len(qs(tr, 'bbh') & qs(te, 'bbh')), 'ifeval', len(qs(tr, 'ifeval') & qs(te, 'ifeval')))
